62:   computed: {
63:     /** 单元顺序取接口返回顺序（一单元、二单元…） */
64:     units() {
65:       const unitMap = new Map()
66:       this.tableData.forEach((floor) => {
67:         (floor.units || []).forEach((unit) => {
68:           const key = this.unitKey(unit)
