73:     },
74:     /** 各单元列宽一致：取全表最大户数作为列数 */
75:     columnsPerRow() {
76:       let max = 0
77:       this.tableData.forEach((floor) => {
78:         (floor.units || []).forEach((unit) => {
79:           const count = (unit.rooms || []).length
80:           if (count > max) max = count
81:         })
82:       })
83:       return Math.max(max, 1)
84:     },
85:     rowStyle() {
86:       const unitColumns = new Array(this.units.length * this.columnsPerRow).fill('minmax(0, 1fr)')
